const VERSION = "34";
const CACHE_NAME = "V" + VERSION;
const OFFLINE_URL = "/offline.html";

// Only immutable root files are precached at startup:
// (All JS/CSS generated by Vite and the Jazz WASM will be cached dynamically)
const STATIC_ASSETS = [
  OFFLINE_URL,
  "/",
  "/index.html",
  "/manifest.json",
  "/favicon.svg"
];

// ============================================================================
// 1. INSTALLATION
// ============================================================================
self.addEventListener("install", (event) => {

  console.log("[SW] Installing version:", CACHE_NAME);
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      for (const url of STATIC_ASSETS) {
        try {
          await cache.add(url);
        } catch (err) {
          console.warn("[SW] Initial precache failed for:", url, err);
        }
      }
    })()
  );
  self.skipWaiting();
});

// ============================================================================
// 2. ACTIVATION AND CLEANUP OF OLD CACHES
// ============================================================================
self.addEventListener("activate", (event) => {

  console.log("[SW] Activating version:", CACHE_NAME);
  event.waitUntil(
    (async () => {
      const cacheNames = await caches.keys();
      await Promise.all(
        cacheNames.map((cache) => {
          if (cache !== CACHE_NAME) {
            console.log("[SW] Deleting old cache:", cache);
            return caches.delete(cache);
          }
        })
      );
    })()
  );
  self.clients.claim();
});

// ============================================================================
// 3. CACHE-FIRST STRATEGY (Specifically for SPA (REACT / VITE))
// ============================================================================
self.addEventListener("fetch", (event) => {

  if (event.request.method !== "GET") return;

  const url = new URL(event.request.url);
  if (url.origin !== location.origin) return;

  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE_NAME);

      // STEP 1: Search for the exact resource in the cache:
      const cachedResponse = await cache.match(event.request);
      if (cachedResponse) {
        return cachedResponse;
      }

      // STEP 2: For an SPA, if navigating to the root or a route, look for /index.html in the cache
      if (event.request.mode === "navigate") {
        const indexResponse = await cache.match("/index.html") || await cache.match("/");
        if (indexResponse) return indexResponse;
      }

      // STEP 3: Otherwise, attempt to fetch from the network
      try {
        const networkResponse = await fetch(event.request);

        if (networkResponse.ok){
          cache.put(event.request, networkResponse.clone());
        }

        return networkResponse;

      } catch (error) {

        console.warn("[SW] Offline, network unreachable for:", url.pathname);

        // STEP 4: In case of network failure during HTML navigation, return offline.html or index.html
        if (event.request.mode === "navigate") {
          const offlinePage = (await cache.match(OFFLINE_URL)) || (await cache.match("/index.html"));
          if (offlinePage) return offlinePage;
        }

        // STEP 5: Return a clean HTTP response instead of throwing an error:
        return new Response("Ressource indisponible hors-ligne", {
          status: 503,
          statusText: "Service Unavailable",
          headers: new Headers({ "Content-Type": "text/plain" }),
        });
      }
    })()
  );
});

